local WatchtowerMaker = {}
local PRODUCTS = {
    simple_wood_watchtower = { name = "Preprost leseni opazovalni stolp", woodCost = 6, ironCost = 1, time = 8, cost = 320, defense = 28, sightRange = 30, happiness = 1, description = "Preprost leseni opazovalni stolp za obzidje." },
    stone_reinforced_tower = { name = "Kamnitookrepljen stolp", woodCost = 4, stoneCost = 3, ironCost = 1, time = 11, cost = 760, defense = 42, sightRange = 45, happiness = 2, prestige = 3, description = "Kamnitookrepljen stolp za trgovce." },
    silver_banded_tower = { name = "Srebrnopasni stolp", woodCost = 4, stoneCost = 3, silverCost = 1, ironCost = 1, time = 15, cost = 1800, defense = 58, sightRange = 60, happiness = 2, prestige = 8, description = "Srebrnopasni stolp za plemiče." },
    gold_trimmed_tower = { name = "Zlatookrasni stolp", woodCost = 4, stoneCost = 3, goldCost = 1, silverCost = 1, ironCost = 1, time = 19, cost = 4000, defense = 72, sightRange = 75, happiness = 3, prestige = 18, description = "Zlatookrasni stolp za visoke plemiče." },
    jewel_set_tower = { name = "Draguljasta stolp", woodCost = 4, stoneCost = 3, goldCost = 2, silverCost = 1, ironCost = 1, jewelCost = 1, time = 23, cost = 8500, defense = 85, sightRange = 88, happiness = 5, prestige = 32, description = "Stolp z draguljem za visoko plemstvo." },
    royal_grand_watchtower = { name = "Kraljevski veliki opazovalni stolp", woodCost = 6, stoneCost = 4, goldCost = 3, silverCost = 2, ironCost = 1, jewelCost = 2, pearlCost = 2, time = 30, cost = 17000, defense = 98, sightRange = 100, happiness = 13, prestige = 65, description = "Veliki kraljevski opazovalni stolp z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tower_workshop = { name = "Stolpna delavnica", cost = { gold = 340, wood = 180, stone = 180, iron = 6 }, upkeep = 8, qualityBonus = 5 },
    fortification_loft = { name = "Fortifikacijska podstrešje", cost = { gold = 1200, wood = 320, stone = 360, silver = 6, marble = 4 }, upkeep = 28, qualityBonus = 18 },
    master_tower_atelier = { name = "Mojstrski stolpni atelje", cost = { gold = 3000, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 70, qualityBonus = 30 },
    royal_fortification_palace = { name = "Kraljevska fortifikacijska palača", cost = { gold = 13000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
WatchtowerMaker.woodStock = 22; WatchtowerMaker.stoneStock = 16; WatchtowerMaker.ironStock = 10; WatchtowerMaker.silverStock = 6; WatchtowerMaker.goldStock = 6; WatchtowerMaker.jewelStock = 4; WatchtowerMaker.pearlStock = 4
WatchtowerMaker.productStock = {}; WatchtowerMaker.buildings = {}; WatchtowerMaker.maker = nil; WatchtowerMaker.activeMaking = {}; WatchtowerMaker.totalProducts = 0; WatchtowerMaker.dayTimer = 0
function WatchtowerMaker.init() WatchtowerMaker.woodStock=22; WatchtowerMaker.stoneStock=16; WatchtowerMaker.ironStock=10; WatchtowerMaker.silverStock=6; WatchtowerMaker.goldStock=6; WatchtowerMaker.jewelStock=4; WatchtowerMaker.pearlStock=4; WatchtowerMaker.productStock={}; WatchtowerMaker.buildings={}; WatchtowerMaker.maker=nil; WatchtowerMaker.activeMaking={}; WatchtowerMaker.totalProducts=0; WatchtowerMaker.dayTimer=0; print("[WatchtowerMaker] Royal Watchtower Maker System initialized (6 products, 4 buildings)") end
function WatchtowerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=620+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WatchtowerMaker.maker={name=n or ("Stolpar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stolpar najet: %s (spretnost: %d)",WatchtowerMaker.maker.name,s),"success") end; return true end
function WatchtowerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WatchtowerMaker.build(id) local ok,e=WatchtowerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WatchtowerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WatchtowerMaker.getQualityBonus() local b=0; for _,bd in ipairs(WatchtowerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WatchtowerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WatchtowerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.stoneCost and WatchtowerMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.ironCost and WatchtowerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and WatchtowerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WatchtowerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WatchtowerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WatchtowerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WatchtowerMaker.buildings==0 then return false,"Potrebna stolpna delavnica" end; if not WatchtowerMaker.maker then return false,"Potreben stolpar" end; return true end
function WatchtowerMaker.make(pt,qty) qty=qty or 1; local ok,e=WatchtowerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WatchtowerMaker.woodStock=WatchtowerMaker.woodStock-d.woodCost*qty end; if d.stoneCost then WatchtowerMaker.stoneStock=WatchtowerMaker.stoneStock-d.stoneCost*qty end; if d.ironCost then WatchtowerMaker.ironStock=WatchtowerMaker.ironStock-d.ironCost*qty end; if d.silverCost then WatchtowerMaker.silverStock=WatchtowerMaker.silverStock-d.silverCost*qty end; if d.goldCost then WatchtowerMaker.goldStock=WatchtowerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WatchtowerMaker.jewelStock=WatchtowerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WatchtowerMaker.pearlStock=WatchtowerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WatchtowerMaker.maker then t=math.max(1,t-math.floor(WatchtowerMaker.maker.skill/12)) end; table.insert(WatchtowerMaker.activeMaking,{id="watchtower_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,sightRange=d.sightRange or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WatchtowerMaker.completeMaking(m) local q=1.0+(WatchtowerMaker.getQualityBonus()/100); if WatchtowerMaker.maker then q=q+(WatchtowerMaker.maker.skill/140) end; q=math.min(2.5,q); WatchtowerMaker.productStock[m.productType]=(WatchtowerMaker.productStock[m.productType] or 0)+m.quantity; WatchtowerMaker.totalProducts=WatchtowerMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.sightRange>0 and _G.state then _G.state.sightRange=(_G.state.sightRange or 0)+m.sightRange end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WatchtowerMaker.maker then WatchtowerMaker.maker.itemsMade=WatchtowerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WatchtowerMaker.maker.skill=math.min(100,WatchtowerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stolp izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"watchtower.completed",{productName=m.productName,defense=m.defense,sightRange=m.sightRange,prestige=m.prestige,happiness=m.happiness}) end end
function WatchtowerMaker.update(dt) if not _G.state then return end; WatchtowerMaker.dayTimer=WatchtowerMaker.dayTimer+dt; if WatchtowerMaker.dayTimer>=30 then WatchtowerMaker.dayTimer=0; for i=#WatchtowerMaker.activeMaking,1,-1 do local m=WatchtowerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WatchtowerMaker.completeMaking(m); table.remove(WatchtowerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WatchtowerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WatchtowerMaker.maker then tu=tu+17 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WatchtowerMaker.getStats() return {woodStock=WatchtowerMaker.woodStock,stoneStock=WatchtowerMaker.stoneStock,ironStock=WatchtowerMaker.ironStock,silverStock=WatchtowerMaker.silverStock,goldStock=WatchtowerMaker.goldStock,jewelStock=WatchtowerMaker.jewelStock,pearlStock=WatchtowerMaker.pearlStock,productStock=WatchtowerMaker.productStock,numBuildings=#WatchtowerMaker.buildings,hasMaker=WatchtowerMaker.maker~=nil,makerName=WatchtowerMaker.maker and WatchtowerMaker.maker.name or "—",makerSkill=WatchtowerMaker.maker and WatchtowerMaker.maker.skill or 0,activeMaking=#WatchtowerMaker.activeMaking,totalProducts=WatchtowerMaker.totalProducts} end
return WatchtowerMaker
